<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Pointly POS | Add Staff</title><?= view('partials/styles') ?></head><body><div class="app-shell"><?= view('partials/nav', ['active' => 'users']) ?><main class="content"><header class="topbar"><div><p class="eyebrow">Access management</p><h1>Add staff account</h1><p class="subtitle">Create a secure account for a POS staff member.</p></div><div class="profile"><div class="avatar">AD</div> Admin account</div></header><section class="panel"><?php if (session()->getFlashdata('error')): ?><div class="form-error"><?= esc(session()->getFlashdata('error')) ?></div><?php endif; ?><form action="<?= base_url('users/create') ?>" method="post" enctype="multipart/form-data"><div class="form-grid"><div class="field"><label for="username">Username</label><input class="input" id="username" name="username" value="<?= old('username') ?>" required></div><div class="field"><label for="full_name">Full name</label><input class="input" id="full_name" name="full_name" value="<?= old('full_name') ?>" required></div><div class="field"><label for="role">Role</label><select class="input" id="role" name="role"><option>Staff</option><option>Cashier</option><option>Manager</option><option>Administrator</option></select></div><div class="field"><label for="password">Password</label><input class="input" type="password" id="password" name="password" minlength="6" required></div><div class="field full"><label for="avatar">Avatar (JPG or PNG, maximum 2 MB)</label><input class="input" type="file" id="avatar" name="avatar" accept=".jpg,.jpeg,.png"></div></div><div class="form-actions"><button class="button" type="submit">Save staff account</button><a class="button secondary" href="<?= base_url('users') ?>">Cancel</a></div></form></section></main></div></body></html>
